arguments.command:
cd /workspace/repo && python -c "
from textkit.numbers import ordinal
# negative
try:
    ordinal(-1)
    print('NEG FAIL: no error')
except ValueError as e:
    print('NEG OK:', e)
# non-int
for bad in [2.0, '3', None, [1], True, False]:
    try:
        ordinal(bad)
        print('TYPE FAIL for', bad)
    except TypeError as e:
        print('TYPE OK for', bad, ':', e)
"

